(6682265, 999303, 108580, '<td valign="top">Technically adept photo-shopping, with good base images to work from. But I wouldn''t say she looks weird, certainly normal when compared with other images in this challenge, I mean the Rocky Horror Picture Show has been around for decades and this has that feel to it.</td>', 'Technically adept photo-shopping, with good base images to work from. But I wouldn''t say she looks weird, certainly normal when compared with other images in this challenge, I mean the Rocky Horror Picture Show has been around for decades and this has that feel to it.', '2012-02-18 15:22:33.000000', NULL, 1),
(6682266, 998326, 108580, '<td valign="top">Yup, that''s weird :) Semper?</td>', 'Yup, that''s weird :) Semper?', '2012-02-18 15:23:04.000000', NULL, 1),
(6682267, 999261, 108580, '<td valign="top">Truly weird. I almost expect to see a metal winder out her back. Great work, PP.</td>', 'Truly weird. I almost expect to see a metal winder out her back. Great work, PP.', '2012-02-18 15:23:53.000000', NULL, 1),
(6682268, 999193, 108580, '<td valign="top">The music rocked. The mullets, ankle warmers and zits didn''t. DMC.</td>', 'The music rocked. The mullets, ankle warmers and zits didn''t. DMC.', '2012-02-18 15:24:25.000000', NULL, 1),
(6682295, 999309, 49018, '<td valign="top">Not as strange as refusing a ribbon, I bet :D<br/>Really good idea and implementation. I just switched calibration off on my display, and it works great nonetheless, somebody knows his business :)</td>', 'Not as strange as refusing a ribbon, I bet :DReally good idea and implementation. I just switched calibration off on my display, and it works great nonetheless, somebody knows his business :)', '2012-02-18 16:49:18.000000', NULL, 1),
(6682297, 999226, 49018, '<td valign="top">Pretty close indeed :)</td>', 'Pretty close indeed :)', '2012-02-18 16:51:55.000000', NULL, 1),
(6682298, 998590, 49018, '<td valign="top">Hahahah, uber geeky. I would have liked it even better with a less tongue-in-cheek expression, ''saving star wars'' kind of guy..<br/>But I like it, very funny.</td>', 'Hahahah, uber geeky. I would have liked it even better with a less tongue-in-cheek expression, ''saving star wars'' kind of guy..But I like it, very funny.', '2012-02-18 16:53:43.000000', NULL, 1),
(6682304, 999327, 49018, '<td valign="top">Funny. There are three things that I feel could have helped blending his figure better in the scene. Faking the shape of the legs underwater, rather than their reflections, even if the water surface is obviously quite reflective at this angle.Applying a bit of toning to the whole image and angling the shadow on his body a bit more towards the viewer. Faking big waves rather than big sprays of water would have been more convincing as well.<br/> <br/>Love the old man peacefully contemplating the big boy in transit :D</td>', 'Funny. There are three things that I feel could have helped blending his figure better in the scene. Faking the shape of the legs underwater, rather than their reflections, even if the water surface is obviously quite reflective at this angle.Applying a bit of toning to the whole image and angling the shadow on his body a bit more towards the viewer. Faking big waves rather than big sprays of water would have been more convincing as well. Love the old man peacefully contemplating the big boy in transit :D', '2012-02-18 17:03:47.000000', NULL, 1),
(6682305, 998388, 49018, '<td valign="top">Live long and prosper..</td>', 'Live long and prosper..', '2012-02-18 17:05:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6682306, 999318, 49018, '<td valign="top">Hahahah, brilliant!<br/>Turning this challenge upside down was not that straightforward at all, really good thinking.<br/>Best in show, full stop.<br/>10</td>', 'Hahahah, brilliant!Turning this challenge upside down was not that straightforward at all, really good thinking.Best in show, full stop.10', '2012-02-18 17:09:24.000000', NULL, 1),
(6682319, 999330, 49018, '<td valign="top">Nice idea. I like it because it''s somewhat about the psychology of being different and strange, the being estranged, not the strangeness in itself. So much less literal than most other entries.<br/>I think a pretty strong postprocessing, to make it more dramatic, would have made an high scorer of this, perhaps something on the lines of many superhero movies, as the pose reminds a bit of that.<br/>Or a moving pose, a man grasping at his face inside the bag, exposed, or something to that lines. I would have scored that very high, independently from the PP, but I don''t know if others would have liked it as well :)<br/>Sorry, rambling thoughts on what kind of story this image could evoke.</td>', 'Nice idea. I like it because it''s somewhat about the psychology of being different and strange, the being estranged, not the strangeness in itself. So much less literal than most other entries.I think a pretty strong postprocessing, to make it more dramatic, would have made an high scorer of this, perhaps something on the lines of many superhero movies, as the pose reminds a bit of that.Or a moving pose, a man grasping at his face inside the bag, exposed, or something to that lines. I would have scored that very high, independently from the PP, but I don''t know if others would have liked it as well :)Sorry, rambling thoughts on what kind of story this image could evoke.', '2012-02-18 17:22:43.000000', NULL, 1),
(6682321, 998620, 49018, '<td valign="top">In the endless sequence of distorted faces, this one is actually outstanding.<br/>Good job, straight from a very good illustration.</td>', 'In the endless sequence of distorted faces, this one is actually outstanding.Good job, straight from a very good illustration.', '2012-02-18 17:24:30.000000', NULL, 1),
(6682322, 998339, 49018, '<td valign="top">Stranger and estranged.</td>', 'Stranger and estranged.', '2012-02-18 17:24:50.000000', NULL, 1),
(6682323, 999093, 108580, '<td valign="top">ROFL that''s not half bad :)</td>', 'ROFL that''s not half bad :)', '2012-02-18 17:24:55.000000', NULL, 1),
(6682325, 999214, 49018, '<td valign="top">The strangeness is in the mind, and in the beholder too. Who, sitting over there, wouldn''t regard the little, wingless people as a bit peculiar?</td>', 'The strangeness is in the mind, and in the beholder too. Who, sitting over there, wouldn''t regard the little, wingless people as a bit peculiar?', '2012-02-18 17:28:23.000000', NULL, 1),
